struct msg_data {
    long mtype;          // Required first member
    char mtext[128];
};

int msqid = 100;
size_t msgsz = sizeof(((struct msg_data*)0)->mtext);
int flags = IPC_NOWAIT | MSG_NOERROR; // Example flags

// Send
struct msg_data send_buf = { .mtype = 1, .mtext = "Hello" };
msgsnd(msqid, &send_buf, msgsz, flags);

// Receive
struct msg_data recv_buf;
long msgtyp = 1; // 0: first message; >0: specific type
msgrcv(msqid, &recv_buf, msgsz, msgtyp, flags);
